<?php if ($billingEligible) { ?>
<section class="cpo-panel cpo-billing-workflow" id="billing-workflow">
  <div class="cpo-panel-head"><div><h2>Invoice &amp; customer receipt</h2><p>A guided staff workflow that saves the invoice, payment and bank entry as native records.</p></div><span class="cpo-badge"><?php echo !empty($billingState['invoice']) ? 'INVOICE LINKED' : 'ORDER READY'; ?></span></div>
  <?php if (!$billingCanRead) { ?><div class="cpo-notice cpo-notice-warning">You need invoice read permission to access the collection workflow.</div>
  <?php } elseif ($billingState) { $billingOrder=$billingState['order'];$billingInvoice=$billingState['invoice'];$billingSummary=$billingState['summary'];$billingOrderStatus=isset($billingOrder->status)?(int)$billingOrder->status:(int)$billingOrder->statut; ?>
    <ol class="cpo-billing-steps">
      <li class="done"><strong>1</strong><span>Validated sales order<small><?php echo dol_escape_htmltag($billingOrder->ref); ?></small></span></li>
      <li class="<?php echo $billingInvoice?'done':'active'; ?>"><strong>2</strong><span>Invoice draft<small>Native invoice</small></span></li>
      <li class="<?php echo $billingInvoice&&(int)$billingInvoice->status>0?'done':''; ?>"><strong>3</strong><span>Validate invoice</span></li>
      <li class="<?php echo $billingSummary&&(float)$billingSummary['paid']>0?'done':''; ?>"><strong>4</strong><span>Record receipt<small>Partial or full</small></span></li>
    </ol>
    <?php if ($billingInvoice) { ?><div class="cpo-billing-summary"><div><span>Invoice</span><strong><?php echo dol_escape_htmltag($billingInvoice->ref); ?></strong></div><div><span>Total</span><strong><?php echo price($billingSummary['total']).' '.dol_escape_htmltag($billingSummary['currency']); ?></strong></div><div><span>Paid</span><strong><?php echo price($billingSummary['paid']).' '.dol_escape_htmltag($billingSummary['currency']); ?></strong></div><div><span>Remaining</span><strong><?php echo price($billingSummary['remaining']).' '.dol_escape_htmltag($billingSummary['currency']); ?></strong></div></div><?php } ?>
    <?php foreach($billingState['receipts'] as $receipt){ if(in_array($receipt['status'],array('native_created','bank_posted','correction_required'),true)){ ?><div class="cpo-notice cpo-notice-warning"><strong>Receipt recovery</strong><br><?php echo dol_escape_htmltag($receipt['payment_reference'].' · '.price($receipt['amount']).' '.$receipt['currency_code'].' · '.$receipt['status']); ?><?php if($receipt['status']!=='correction_required'){ ?><form method="post" class="cpo-inline-form"><input type="hidden" name="token" value="<?php echo newToken(); ?>"><input type="hidden" name="id" value="<?php echo (int)$id; ?>"><input type="hidden" name="action" value="billing_resume_receipt"><input type="hidden" name="billing_marker_id" value="<?php echo (int)$receipt['rowid']; ?>"><button class="button smallpaddingimp">Verify and resume</button></form><?php }else{ ?><br><small>The action stopped because the original evidence changed. A manual financial correction is required; no replacement payment will be created.</small><?php } ?></div><?php }} ?>
    <div class="cpo-billing-actions">
      <?php if ($billingCanCreate && !$billingInvoice && $billingOrderStatus===Commande::STATUS_VALIDATED) { ?><form method="post"><input type="hidden" name="token" value="<?php echo newToken(); ?>"><input type="hidden" name="id" value="<?php echo (int)$id; ?>"><input type="hidden" name="action" value="billing_create_invoice"><input type="hidden" name="billing_request_key" value="<?php echo dol_escape_htmltag($billingRequestKey); ?>"><button class="button button-save">2. Create invoice draft</button></form><?php } ?>
      <?php if ($billingCanValidate && $billingInvoice && (int)$billingInvoice->status===Facture::STATUS_DRAFT) { ?><form method="post" onsubmit="return confirm('Validate this invoice? No email will be sent.');"><input type="hidden" name="token" value="<?php echo newToken(); ?>"><input type="hidden" name="id" value="<?php echo (int)$id; ?>"><input type="hidden" name="action" value="billing_validate_invoice"><button class="button button-save">3. Validate invoice</button></form><?php } ?>
    </div>
    <?php if ($billingCanPay && $billingInvoice && (int)$billingInvoice->status===Facture::STATUS_VALIDATED && (float)$billingSummary['remaining']>0.00001) { ?>
      <form method="post" class="cpo-billing-payment"><input type="hidden" name="token" value="<?php echo newToken(); ?>"><input type="hidden" name="id" value="<?php echo (int)$id; ?>"><input type="hidden" name="action" value="billing_post_receipt"><input type="hidden" name="billing_request_key" value="<?php echo dol_escape_htmltag($billingRequestKey); ?>">
        <div class="cpo-context-grid"><label class="cpo-field"><span>Amount (<?php echo dol_escape_htmltag($billingSummary['currency']); ?>)</span><input required type="number" min="0.01" max="<?php echo dol_escape_htmltag((string)$billingSummary['remaining']); ?>" step="0.01" name="receipt_amount" value="<?php echo dol_escape_htmltag((string)$billingSummary['remaining']); ?>"></label><label class="cpo-field"><span>Same-currency bank</span><select required name="bank_account_id"><option value="">—</option><?php foreach($billingState['banks'] as $bank){ ?><option value="<?php echo (int)$bank['rowid']; ?>"><?php echo dol_escape_htmltag(($bank['label']?:$bank['bank']).' · '.$bank['currency']); ?></option><?php } ?></select></label><label class="cpo-field"><span>Payment method</span><select required name="payment_code"><option value="">—</option><?php foreach($billingState['payment_modes'] as $mode){ ?><option value="<?php echo dol_escape_htmltag($mode['code']); ?>"><?php echo dol_escape_htmltag($mode['libelle'].' · '.$mode['code']); ?></option><?php } ?></select></label><label class="cpo-field"><span>Date</span><input required type="date" name="payment_date" value="<?php echo dol_escape_htmltag(dol_print_date(dol_now(),'%Y-%m-%d')); ?>"></label></div>
        <label class="cpo-field"><span>Bank receipt reference</span><input required maxlength="255" name="payment_reference" placeholder="Bank transfer or receipt reference"></label>
        <?php if (empty($billingState['banks'])) { ?><div class="cpo-notice cpo-notice-warning">No open bank account is available in <?php echo dol_escape_htmltag($billingSummary['currency']); ?>. Automatic currency conversion is not allowed.</div><?php } ?>
        <button class="button button-save"<?php echo empty($billingState['banks'])?' disabled':''; ?>>4. Record native receipt</button>
      </form>
    <?php } ?>
    <p class="cpo-commercial-boundary">This workflow does not allow standalone payments, overpayments, automatic currency conversion or external sending.</p>
  <?php } ?>
</section>
<?php } ?>
